# Since we don't have the exact library functions, I'll implement the logic based on the prompt instructions

def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if inp != out:
            changed.append((i, inp, out))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Simple approach: find first differing character
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            # Check if it's a substitution
            if len(s_in) == len(s_out):
                return (c1, c2, i)
            # If lengths differ, it could be insertion/deletion
            elif len(s_in) < len(s_out):
                # Insertion case
                return (c1, c2, i)
            else:
                # Deletion case  
                return (c1, c2, i)

    # If we reach here, check length difference
    if len(s_in) != len(s_out):
        # This means we have insertion/deletion at end
        if len(s_in) < len(s_out):
            return (s_in[-1] if s_in else '', s_out[-1], len(s_in)-1)
        else:
            return (s_in[-1], '', len(s_in)-1)

    return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules."""
    # For now, let's look at simple substitutions
    candidates = []

    # Look for simple character substitutions
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            candidates.append((c1, c2))

    # Also consider longer patterns if they exist
    # Try to match longer substrings that are consistent
    for length in range(min(len(s_in), len(s_out)), 0, -1):
        if length <= 3:  # Max 3 characters as per constraint
            for i in range(len(s_in) - length + 1):
                pattern = s_in[i:i+length]
                # Check if this pattern occurs elsewhere in input
                if s_in.count(pattern) == 1:  # Only occurs once in input
                    replacement = s_out[i:i+length] if len(s_out) >= i+length else s_out[i:]
                    candidates.append((pattern, replacement))

    # Return unique candidates
    seen = set()
    unique_candidates = []
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

def score_rules(inputs, outputs, rules):
    """Score how well rules transform inputs to outputs."""
    total_correct = 0
    for inp, expected_out in zip(inputs, outputs):
        actual_out = inp
        for pattern, replacement in rules:
            actual_out = actual_out.replace(pattern, replacement)
        if actual_out == expected_out:
            total_correct += 1
    return total_correct / len(inputs)

# Now let's apply our analysis
inputs = ['ggydvd', 'fkuy', 'yev', 'ubxagh', 'ahvv']
outputs = ['ggydvd', 'fkawv', 'yev', 'icywcxxgy', 'xyvv']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, inp, out in changed:
    print(f"  {idx}: '{inp}' -> '{out}'")

# Analyze each changed pair
rules_to_try = []

for idx, inp, out in changed:
    print(f"\nAnalyzing pair {idx}: '{inp}' -> '{out}'")
    if idx == 1:  # 'fkuy' -> 'fkawv'
        print("  Character changes: u->a, y->w")
        # Try simple substitutions
        rules_to_try.extend([('u', 'a'), ('y', 'w')])
    elif idx == 3:  # 'ubxagh' -> 'icywcxxgy'
        print("  Multiple character changes:")
        print("  u->i, b->c, x->y, a->w, g->c, h->x")
        # These seem to be multiple individual replacements
        rules_to_try.extend([('u', 'i'), ('b', 'c'), ('x', 'y'), ('a', 'w'), ('g', 'c'), ('h', 'x')])
    elif idx == 4:  # 'ahvv' -> 'xyvv'
        print("  Character changes: a->x, h->y")
        rules_to_try.extend([('a', 'x'), ('h', 'y')])

print(f"\nProposed rules: {rules_to_try}")

# Test scoring
score = score_rules(inputs, outputs, rules_to_try)
print(f"Score with proposed rules: {score}")

